#pragma once
// Core types for the limit order book. Prices are integer ticks end-to-end:
// floating point never participates in matching or priority decisions.
#include <cstdint>

namespace lob {

using Price = std::int64_t;     // ticks (e.g. 1 tick = 0.0001 dollars)
using Qty = std::int64_t;
using OrderId = std::uint64_t;

enum class Side : std::uint8_t { Buy, Sell };
enum class OrderType : std::uint8_t { Limit, Market };

struct Order {
    OrderId id;
    Side side;
    OrderType type;
    Price price;               // ignored for market orders
    Qty quantity;              // remaining quantity
    std::uint64_t sequence;    // global arrival counter for time priority
};

struct Trade {
    OrderId makerId;           // resting order that provided liquidity
    OrderId takerId;           // incoming order that crossed
    Price price;
    Qty quantity;
};

inline const char* toString(Side s) { return s == Side::Buy ? "BUY" : "SELL"; }

}  // namespace lob

#pragma once
// Interface you must implement in src/lob/book.cpp.
#include <cstddef>
#include <optional>
#include <utility>
#include <vector>

#include "lob/types.hpp"

namespace lob {

class OrderBook {
public:
    virtual ~OrderBook() = default;

    // Add a limit order; ids must be unique. Marketable limits cross
    // immediately (matching engine responsibility).
    virtual void addLimit(const Order& order) = 0;

    // Cancel a resting order by id; returns false if unknown or already filled.
    virtual bool cancel(OrderId id) = 0;

    // Execute a market order against the book; appends resulting trades
    // in matching order. Remaining unfilled quantity is discarded
    // (or rejected if the book is empty — document your choice).
    virtual void executeMarket(Side side, Qty quantity, std::vector<Trade>& tradesOut) = 0;

    virtual std::optional<Price> bestBid() const = 0;
    virtual std::optional<Price> bestAsk() const = 0;

    // Depth: (price, quantity) pairs per level, best first, up to `levels`.
    virtual std::vector<std::pair<Price, Qty>> depth(Side side, std::size_t levels) const = 0;
};

}  // namespace lob
